#include <iostream>
#include <memory>
class HasPtr {
public:
  HasPtr(int *p) : ptr(std::unique_ptr<int>(p)), i(0) {}
  HasPtr(const HasPtr& hp) : ptr(std::make_unique<int>(*hp.ptr)), i(hp.i) {} //Copy Constructor
  HasPtr& operator=(const HasPtr& hp){
    ptr.reset(new int(*hp.ptr));
    i = hp.i;
    return *this;
  }
  ~HasPtr() {std::cout << "Destructor called" << std::endl;}
private:
  std::unique_ptr<int> ptr;
  int i;
};
int main() {
  int *x = new int(42);
  HasPtr hp(x);
  HasPtr hp2 = hp; //copy constructor used
  HasPtr hp3;
  hp3 = hp;  //copy assignment used
  return 0;
}
